¿Qué muestra?
bool found = false;
int r = 0;
for (int i = 0; i < 3; i++)
{
    for (int j = 0; j < 3; j++)
    {
        if (i * j == 2) { found = true; break; }
    }
    if (found) break;
    r++;
}
Console.Write(r + "," + found);

